// #d9d257 (6a993d711bef8ed807d9d257) — обрыв практики (сценарий B ручной проверки 14.10): сбой посреди звонка → кандидат
// возвращается на тех. проверку с объяснением, практика не повторяется, официальная остаётся доступной. Кейсы CALL-012, CALL-013.
// Сбой — настоящий: context.setOffline(true) + закрытие WebRTC (как вручную), ответы не подменяются.
// @call — ТРАТИТ кредиты OpenAI (~0,5 минуты голоса). Без звонка экран возврата проверяет practice-after-states.spec.ts.
// НЕ prod-safe: создаёт кандидата «QA-AUTO-CALL-PD-…» (link_only); официальная не тратится (страховка blockCallStarts).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import {
  Candidate, DIALOG_WAV, ONE_TIME, createCandidateLink, candidateRow, launchCandidate, goToPractice, tap, blockCallStarts,
  expectOfficialScreenNoPractice, recheckAndContinue, dropCall, timerSeconds,
} from './support';

test.describe.configure({ mode: 'serial' });

let cand: Candidate | undefined;
let name = '';

test.afterAll(async () => {
  await cand?.browser.close();
});

test.describe('Звонок кандидата — обрыв одноразовой практики (#6a993d711bef8ed807d9d257)', () => {
  test('сбой посреди практики → «מסיימים את התרגול…»; offline «לא הצלחנו לשמור את סיום השיחה…» + «לנסות שוב»; сеть вернулась → technical_failure, экран «נבדוק שוב את הציוד … התרגול עצמו לא חוזר.» @desktop @data @call #6a993d711bef8ed807d9d257', async ({ asUser }) => {
    test.setTimeout(6 * 60_000);
    const business = await asUser('business');
    name = `QA-AUTO-CALL-PD-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}», ссылка ${link} (практика оборвана), не удаляется` });

    cand = await launchCandidate({ width: 390, height: 844 }, DIALOG_WAV);
    const { page, ctx } = cand;
    await goToPractice(page, link);
    await tap(page, 'להתחיל תרגול');
    await expect(page.getByText('מצב תרגול')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible();
    // Звонок идёт: таймер ушёл ниже 2:50 (вручную обрыв был на 38-й секунде).
    await expect.poll(() => timerSeconds(page), { timeout: 60_000 }).toBeLessThanOrEqual(170);

    await dropCall(ctx, page);
    await expect(page.getByText(ONE_TIME.ending)).toBeVisible({ timeout: 10_000 });
    await expect(page.getByText(ONE_TIME.saveFail)).toBeVisible({ timeout: 60_000 });

    await ctx.setOffline(false);
    const end = page.waitForResponse(
      (r) => r.url().includes('/functions/v1/end-candidate-attempt') && r.request().method() === 'POST' && r.ok(),
      { timeout: 60_000 },
    );
    await tap(page, 'לנסות שוב');
    const body = (await (await end).json()) as { attempt?: { status?: string; end_reason?: string }; recording?: unknown };
    expect(body.attempt?.status).toBe('technical_failure');
    expect(body.recording, 'у практики есть запись').toBeNull();

    // Источник: AC4 «מוחזר לבדיקה הטכנית עם הסבר, והניסיון הרשמי נותר זמין»; «אינה חזרה יזומה על התרגול».
    await expect(page.getByText(ONE_TIME.backTitle)).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(ONE_TIME.backReason)).toBeVisible();
    await expect(page.getByText(ONE_TIME.backNotCounted)).toBeVisible();
    await expect(page.getByText(ONE_TIME.backNoRepeat)).toBeVisible();
    await expect(page.getByRole('button', { name: /תרגול/ })).toHaveCount(0);
  });

  test('после обрыва: повторная тех. проверка → «פרטי לקוח לשיחה» с «מוכן, מתחילים», практики нет (и после reload); у бизнеса «בדיקה טכנית החלה», «דוח» = «—» @desktop @data @call #6a993d711bef8ed807d9d257', async ({ asUser }) => {
    test.setTimeout(3 * 60_000);
    expect(cand, 'нет состояния из предыдущего теста').toBeTruthy();
    const { page } = cand!;
    const blocked = await blockCallStarts(page);
    await recheckAndContinue(page);
    await expectOfficialScreenNoPractice(page);
    await page.reload();
    await expectOfficialScreenNoPractice(page);
    expect(blocked.start + blocked.voice, 'попыток старта официальной').toBe(0);

    const business = await asUser('business');
    const row = await candidateRow(business, name);
    await expect(row).toContainText('בדיקה טכנית החלה');
    await expect(row).not.toContainText('הושלמה');
    await expect(row.getByRole('link', { name: /דוח/ })).toHaveCount(0);
  });
});
